


/** Why the buyer is confirming, the email to confirm, and how the code reaches them. */ export type CreateCheckoutCustomerVerificationRequestInput = { /** How the code reaches the buyer. Omit it to use the purpose's default: auto for use_saved_payment_methods, and email for gift_card_purchase and save_payment_method. email emails the code. With use_saved_payment_methods, it answers the same whether or not the email has saved details. sms texts it: for use_saved_payment_methods, to the mobile phone number saved with the email's details; for confirm_saved_payment_method, to the number given with the payment. auto, for use_saved_payment_methods only, lets Flint pick from the email's saved details: it texts the number they carry, or, when they carry none, emails the code when the email has cards saved by email, and sends nothing otherwise, returning CUSTOMER_VERIFICATION_NOT_SENT. The response's channel says which. Required for confirm_saved_payment_method, which takes sms or email, and gift_card_purchase and save_payment_method take only email. */ "channel"?: "email" | "sms" | "auto"; /** Email the buyer typed, with no surrounding spaces. Customers are matched by email without regard to case. Required for gift_card_purchase, save_payment_method, and use_saved_payment_methods, and not allowed for confirm_saved_payment_method. Format: email. maxLength: 255. */ "email"?: string; /** gift_card_purchase: the buyer confirms their email before funding a gift card purchase; Flint emails a code without saving a payment method. save_payment_method: the buyer asked to save the card they are paying with; Flint emails a code to any valid address. use_saved_payment_methods: the buyer asked to use details they saved at this merchant before. By auto, the default, Flint texts or emails a code the way the email's details were saved, and sends nothing when it has none. By email, Flint sends a code only when a customer with this email has saved details, an active card saved by email or with a mobile phone number, and the response is the same either way. By sms, Flint texts the number saved with the email's details. confirm_saved_payment_method: after a payment that sent save_payment_method_phone, the buyer confirms the card it saved. */ "purpose": "gift_card_purchase" | "save_payment_method" | "use_saved_payment_methods" | "confirm_saved_payment_method"; };
